<?php
require_once __DIR__ . '/config/database.php'; requireTenant();
$tenant=currentTenant();
if (!$tenant) { header('Location: tenant-login.php?session=expired'); exit; }
$residences=[]; $bills=[]; $billError=null; $billNotice=null; $pdo=null;
try {
 $pdo=db();
 $statement=$pdo->prepare("SELECT r.id,r.move_in_date,r.status,r.amount_due,u.id AS unit_id,u.unit_number,u.unit_type,u.monthly_rent,a.name AS apartment_name,a.address,a.area FROM reservations r JOIN units u ON u.id=r.unit_id JOIN apartments a ON a.id=u.apartment_id WHERE r.tenant_id=:tenant_id ORDER BY FIELD(r.status,'paid','pending_payment','cancelled'),r.id DESC");
 $statement->execute(['tenant_id'=>(int)$tenant['id']]); $residences=$statement->fetchAll();
 $statement=$pdo->prepare("SELECT b.*,u.unit_number,a.name AS apartment_name FROM tenant_bills b JOIN units u ON u.id=b.unit_id JOIN apartments a ON a.id=u.apartment_id WHERE b.tenant_id=:tenant ORDER BY FIELD(b.status,'unpaid','overdue','submitted','paid'),b.due_date ASC,b.id DESC");
 $statement->execute(['tenant'=>(int)$tenant['id']]); $bills=$statement->fetchAll(); $billsByType=[]; foreach($bills as $bill){$billsByType[$bill['bill_type']]=$bill;}
} catch (Throwable $exception) { $billError=$billError ?: 'Billing is not set up yet. Run sql/migrate_add_billing_policies.sql after backing up your database.'; }
$pageTitle='Tenant portal'; $currentPage='tenant'; require __DIR__ . '/partials/header.php';
?><div class="page-shell checkout-page"><section class="tenant-hero"><div><p class="eyebrow">TENANT PORTAL</p><h1>Welcome, <?= e($tenant['full_name']) ?>.</h1><p>Manage your account, residence details, and property bills.</p></div><a class="button button-outline" href="tenant-logout.php">Sign out</a></section>
<?php if($billError): ?><div class="database-notice" role="status"><strong>Billing unavailable.</strong><span><?= e($billError) ?></span></div><?php endif; ?><?php if($billNotice): ?><div class="success-banner" role="status"><?= e($billNotice) ?></div><?php endif; ?>
<section class="tenant-account-grid"><article class="form-card"><p class="eyebrow">YOUR INFORMATION</p><h2>Tenant details</h2><dl class="tenant-details"><dt>Full name</dt><dd><?= e($tenant['full_name'] ?? '') ?></dd><dt>Email</dt><dd><?= e($tenant['email'] ?? '') ?></dd><dt>Phone</dt><dd><?= e($tenant['phone'] ?? '') ?></dd><dt>Member since</dt><dd><?= e(date('M j, Y',strtotime($tenant['created_at'] ?? 'now'))) ?></dd></dl></article>
<article class="form-card"><p class="eyebrow">YOUR RESIDENCE</p><h2><?= $residences?'Unit records':'No unit yet' ?></h2><?php if(!$residences): ?><p>You have not connected a reservation to this account yet. Browse available homes to choose your unit.</p><a class="button button-dark" href="index.php">Find a home →</a><?php else: ?><div class="tenant-residences"><?php foreach($residences as $r): ?><div class="tenant-residence"><div><strong>Unit <?= e($r['unit_number']) ?></strong><p><?= e($r['apartment_name']) ?> · <?= e($r['area']) ?></p><small><?= e($r['address']) ?></small></div><span class="status-pill status-<?= e($r['status']) ?>"><?= e(str_replace('_',' ',$r['status'])) ?></span><dl><dt>Move-in</dt><dd><?= e(date('M j, Y',strtotime($r['move_in_date']))) ?></dd><dt>Monthly rent</dt><dd><?= pesos((float)$r['monthly_rent']) ?></dd></dl></div><?php endforeach; ?></div><?php endif; ?></article></section>
<section class="billing-section"><div class="section-heading"><div><p class="eyebrow">TENANT BILLING</p><h2>Water, electricity &amp; rent</h2></div><p class="result-note">Your three recurring bill cards stay visible here. Choose a payment option when a bill is posted.</p></div><div class="billing-cards billing-cards-fixed"><?php foreach(['rent'=>'Rent','water'=>'Water','electricity'=>'Electricity'] as $type=>$label): $b=$billsByType[$type]??null; ?><article class="bill-card <?= $type==='rent' && $b && in_array($b['status'],['unpaid','overdue'],true) ? 'bill-card-rent-unpaid' : '' ?>"><div class="bill-card-top"><div><p class="eyebrow"><?= e($label) ?><?= $type==='rent' && $b && in_array($b['status'],['unpaid','overdue'],true) ? ' · UNPAID' : '' ?></p><h3><?= e($b['description']??($label.' bill not posted')) ?></h3><p><?= $b ? 'Unit '.e($b['unit_number']).' · '.e($b['apartment_name']) : 'Your property administrator will post this bill here.' ?></p></div><?php if($b): ?><span class="status-pill status-<?= e($b['status']) ?>"><?= e(str_replace('_',' ',$b['status'])) ?></span><?php endif; ?></div><?php if($b): ?><div class="bill-due-row"><strong><?= pesos((float)$b['amount']) ?></strong><span>Due <?= e(date('M j, Y',strtotime($b['due_date']))) ?></span></div><?php if(in_array($b['status'],['unpaid','overdue'],true)): ?><a class="button button-dark bill-pay-button" href="tenant-bill-payment.php?bill_id=<?= (int)$b['id'] ?>">Pay this bill →</a><?php elseif($b['status']==='submitted'): ?><p class="bill-reference bill-pending-note">Payment submitted · <code><?= e((string)$b['payment_reference']) ?></code></p><?php elseif($b['payment_reference']): ?><p class="bill-reference">Payment recorded · <code><?= e($b['payment_reference']) ?></code></p><?php endif; ?><?php else: ?><p class="bill-reference">No amount or due date has been posted yet.</p><?php endif; ?></article><?php endforeach; ?></div></section></div><?php require __DIR__ . '/partials/footer.php'; ?>
